output_text:
[
  {
    "id": "no_carts_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles because those aisles are only wide enough for pedestrians.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not push a cart into a single-file aisle; the cart must be left outside before entry.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After returning from a single-file aisle without the cart, the agent is obliged to reclaim the parked cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "leaveSingleFileCartless": {
          "pre": {
            "and": [
              "singleFileAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "wideAisle"
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileCartless",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "narrow_aisles_not_shortcuts",
    "text": "If an agent enters a single-file shelf aisle without a cart, they should do so only to collect something there, not to use it as a shortcut.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileCartlessFromWide": {
          "pre": {
            "and": [
              {
                "not": "singleFileAisle"
              },
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileCartlessFromWide",
      "discharge": {
        "and": [
          "singleFileAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_parking_points",
    "text": "Carts may be set down only at designated parking points such as the cart bay or the mouths of pedestrian-only aisles.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "approvedCartParking": {
          "or": [
            "cartBay",
            "aisleMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "approvedCartParking"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_faces",
    "text": "Shelf items accessed from open or cart-accessible shelf faces must be loaded with the cart present, unlike items inside single-file pedestrian aisles.",
    "abstraction": {
      "state_properties": {
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "lower_shelf_bays_no_reverse",
    "text": "At lower north-facing shelf bottlenecks, a cart user should leave by continuing east or dropping south, not by reversing west or going north into the shelf area.",
    "abstraction": {
      "state_properties": {
        "lowerNorthShelfBottleneck": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "lowerNorthShelfBottleneck",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_flow_in_wide_aisles",
    "text": "In broad horizontal cart aisles, carts should follow one-way eastbound traffic and should not be pushed west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  }
]
